import re

def normalize_identifier(name: str, strip_leading_underscores: bool = False) -> str:
    if not name or not isinstance(name, str):
        raise ValueError('Identifier cannot be empty')
    if not re.match(r'^[a-zA-Z0-9_-]+$', name):
        raise ValueError('Invalid characters in identifier')

    s = re.sub(r'[-\s]+', '_', name)
    s = re.sub(r'([A-Z]+)([A-Z][a-z])', r'\1_\2', s)
    s = re.sub(r'([a-z\d])([A-Z])', r'\1_\2', s).lower()
    s = re.sub(r'_+', '_', s)

    if strip_leading_underscores:
        s = s.lstrip('_')
    return s
